/*
 * A205844  s(k)-s(j), where the pairs (k,j) are given by A205842 and A205843,
 *          and s(k) denotes the (k+1)-st Fibonacci number.
 * https://oeis.org/A205844
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = s(k) - s(j), where (k,j) are the n‑th terms of the
 *            interleaving of A205842 and A205843. s(k) is the (k+1)-st
 *            Fibonacci number. The terms are generated by enumerating all
 *            pairs k > j ≥ 0 with s(k) ≡ s(j) (mod 3), listing them in
 *            increasing order of k, then of j, but skipping the pair (1,0)...
 * Range:     u8 n <= 19, u16 n <= 49, u32 n <= 49, u64 n <= 49, u128 n <= 49,
 *            big any n
 * Helpers:   grow_seq, seq_alloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>

/* The build supplies the integer types seq_t and idx_t.  */
#include "../utils/seq_alloc.h"      /* seq_alloc(uint64_t) */
#include "../utils/grow_seq.h"       /* grow_seq(seq_t **, size_t *, size_t) */

#define FIB_MAX 2048          /* enough for any n up to ~10000 */

/* Pre‑computed Fibonacci numbers: fib[i] = F_{i+1} = s(i). */
static seq_t fib[FIB_MAX];
static bool fib_init = false;

/* Initialise the Fibonacci table. */
static void init_fib(void)
{
    if (fib_init)
        return;
    fib[0] = 1;           /* F1 */
    fib[1] = 1;           /* F2 */
    for (size_t i = 2; i < FIB_MAX; ++i)
        fib[i] = fib[i - 1] + fib[i - 2];
    fib_init = true;
}

/* State for the next pair enumeration. */
static idx_t enum_k = 1;   /* current k (first pair k=1) */
static idx_t enum_j = 0;   /* current j (first j=0) */

/* Return the next difference s(k)-s(j) in the required order. */
static seq_t next_diff(void)
{
    init_fib();

    while (true) {
        /* Ensure k stays within bounds.  Must not happen for n ≤ 10000. */
        if (enum_k >= (idx_t)(FIB_MAX - 1))
            return 0;

        /* Scan j for this k.  When finished, advance k. */
        if (enum_j >= enum_k) {
            ++enum_k;
            enum_j = 0;
            continue;
        }

        /* Skip the duplicate pair with j = 1 (s(1) = s(0)). */
        if (enum_j == 1) {
            ++enum_j;
            continue;
        }

        /* Skip the zero difference (k = 1, j = 0). */
        if (enum_k == 1 && enum_j == 0) {
            ++enum_j;
            continue;
        }

        /* Check residue modulo 3. */
        seq_t fk = fib[(size_t)enum_k];
        seq_t fj = fib[(size_t)enum_j];
        if ((fk % 3) != (fj % 3)) {
            ++enum_j;
            continue;
        }

        /* Produce the difference and advance j for the next call. */
        seq_t diff = fk - fj;
        ++enum_j;
        return diff;
    }
}

/* Cache for already generated terms. */
static seq_t *cache = NULL;
static size_t cache_len = 0;
static size_t cache_cap = 0;

/* Grow the cache to accommodate needed size. */
static void grow_cache(size_t new_cap)
{
    if (cache == NULL) {
        cache = seq_alloc(new_cap);
        cache_cap = new_cap;
        return;
    }

    if (new_cap <= cache_cap)
        return;

    grow_seq((seq_t **)&cache, &cache_cap, new_cap);
}

/* Ensure that cache contains at least n terms. */
static void ensure_cache(idx_t n)
{
    if ((idx_t)cache_len >= n)
        return;

    if (cache == NULL)
        grow_cache(1024); /* initial capacity */

    for (idx_t i = cache_len; i < n; ++i) {
        seq_t val = next_diff();
        if (cache_len + 1 > cache_cap)
            grow_cache(cache_cap * 2);
        cache[cache_len++] = val;
    }
}

/* Public OEIS function. */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;            /* undefined for offset 1, guard value */

    ensure_cache(n);
    return cache[n - 1];
}
